"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@ui/button";
import { Container, ContainerBody, ContainerFooter, ContainerHeader } from "@ui/container";
import { Empty, EmptyDescription } from "@ui/empty";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { Skeleton } from "@ui/skeleton";
import { Tooltip } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { calculateCostEstimate, costEstimateDefaultLimits, costEstimateLabels, costEstimateLimitsValid, costEstimateUsageMatches, costEstimateUsageValid } from "./cost-estimate-data";
import { CostEstimateSummary } from "./cost-estimate-summary";
import { CostEstimateUsage } from "./cost-estimate-usage";
import type { CostEstimateField, CostEstimateProps } from "./cost-estimate-types";
export function CostEstimate({ value, onValueChange, rateCard, regions, presets = [], limits = costEstimateDefaultLimits, defaultInputs, state = "ready", statusMessage, saveState = { status: "idle" }, actions, labels: overrides, title, locale = "zh-CN", className, ...props }: CostEstimateProps) {
    const labels = { ...costEstimateLabels, ...overrides };
    const Info = useIcon("doc-info-item");
    const Save = useIcon("arrow-down");
    const [invalidDrafts, setInvalidDrafts] = useState<CostEstimateField[]>([]);
    const [revision, setRevision] = useState(0);
    const saving = useRef(false);
    const onInvalid = useCallback((field: CostEstimateField, invalid: boolean) => setInvalidDrafts((current) => {
        if (current.includes(field) === invalid)
            return current;
        return invalid ? [...current, field] : current.filter((item) => item !== field);
    }), []);
    const region = regions.find((item) => item.id === value.regionId);
    const loading = state === "loading" || (state !== "error" && rateCard !== null && rateCard.regionId !== value.regionId);
    const limitsValid = costEstimateLimitsValid(limits);
    const usageValid = costEstimateUsageValid(value, limits);
    const result = state !== "error" && !loading && region && rateCard ? calculateCostEstimate(value, rateCard, limits) : null;
    const preset = presets.find((item) => costEstimateUsageMatches(item.usage, value));
    const pending = saveState.status === "pending";
    useEffect(() => { if (!pending)
        saving.current = false; }, [pending]);
    const saved = saveState.status === "succeeded" && saveState.fingerprint === result?.fingerprint && invalidDrafts.length === 0;
    const resetValid = defaultInputs && costEstimateUsageValid(defaultInputs, limits) && regions.some((item) => item.id === defaultInputs.regionId);
    const resetUnchanged = defaultInputs && costEstimateUsageMatches(defaultInputs, value) && defaultInputs.regionId === value.regionId && defaultInputs.billing === value.billing && invalidDrafts.length === 0;
    function save() {
        if (saving.current || pending || state !== "ready" || !result || invalidDrafts.length || !actions?.onSave)
            return;
        saving.current = true;
        try {
            actions.onSave(result);
        }
        finally {
            queueMicrotask(() => { saving.current = false; });
        }
    }
    return <Container {...props} data-block="cost-estimate" data-state={state} aria-busy={loading || undefined} className={cn("@container w-full max-w-xl", className)}>
    <ContainerHeader className="py-1.5">
      <div className="flex min-w-0 items-center gap-2"><h2 className="break-words text-body font-medium text-fg-default">{title ?? labels.title}</h2><Tooltip content={labels.description}><Button iconOnly variant="ghost" size="xs" aria-label={labels.description}><Info aria-hidden/></Button></Tooltip></div>
    </ContainerHeader>
    <ContainerBody>
      {state === "stale" && <div className="mb-4"><InlineNotice tone="warning" variant="emphasized"><InlineNoticeContent>{statusMessage ?? labels.stale}</InlineNoticeContent></InlineNotice></div>}
      {loading ? <div role="status" className="space-y-3"><span className="sr-only">{labels.loading}</span><Skeleton className="h-8 w-40"/><Skeleton className="h-5 w-full"/><Skeleton className="h-14 w-full"/></div> : result ? <CostEstimateSummary result={result} rateCard={rateCard!} labels={labels} locale={locale} onBillingChange={(billing) => onValueChange({ ...value, billing }, "billing")}/> : state === "error" || rateCard !== null || !region ? <InlineNotice tone="danger" role="alert" variant="emphasized"><InlineNoticeContent>{statusMessage ?? (state === "error" ? labels.error : labels.invalid)}</InlineNoticeContent></InlineNotice> : <Empty reason="no-data" scope="inline"><EmptyDescription>{labels.noRates}</EmptyDescription></Empty>}
      {(!result || state === "stale") && actions?.onRetry && <Button size="sm" variant="secondary" className="mt-3" onClick={actions.onRetry}>{labels.retry}</Button>}
    </ContainerBody>
    <ContainerBody>
      <div className="mb-4 flex flex-wrap items-start justify-between gap-3"><div><h3 className="text-body font-medium text-fg-default">{labels.usage}</h3><p className="mt-1 text-label text-fg-subtle">{preset ? `${labels.preset} · ${preset.label}` : labels.custom}</p></div>
        {presets.length > 0 && <div role="group" aria-label={labels.presets} className="flex flex-wrap gap-1">{presets.map((item) => <Button key={item.id} size="sm" variant="tertiary" active={preset?.id === item.id} disabled={!costEstimateUsageValid(item.usage, limits)} onClick={() => { setRevision((current) => current + 1); onValueChange({ ...value, ...item.usage }, "preset"); }}>{item.label}</Button>)}</div>}
      </div>
      {limitsValid && usageValid ? <CostEstimateUsage value={value} result={result} rateCard={rateCard} limits={limits} labels={labels} locale={locale} disabled={false} revision={revision} onInvalid={onInvalid} onChange={(field, next) => onValueChange({ ...value, [field]: next }, "field")}/> : <p role="alert" className="text-label text-fg-danger">{labels.invalid}</p>}
    </ContainerBody>
    <ContainerFooter className="justify-between gap-3">
      <div className="min-w-0 space-y-1 text-label text-fg-subtle"><p className="break-words">{result?.currency ?? "—"} · {labels.excludingTax} · {region?.location ?? "—"}</p>{result && <p>{labels.rateVersion} {result.rateCardVersion}</p>}
        {saved && <p role="status" className="text-fg-success">{labels.saved}</p>}{saveState.status === "error" && <p role="alert" className="text-fg-danger">{saveState.message}</p>}
      </div>
      <div className="flex flex-wrap gap-2">{defaultInputs && <Button variant="ghost" size="sm" disabled={!resetValid || resetUnchanged} onClick={() => { setRevision((current) => current + 1); onValueChange({ ...defaultInputs }, "reset"); }}>{labels.reset}</Button>}{actions?.onSave && <Button size="sm" leadingIcon={Save} loading={pending} disabled={!result || state !== "ready" || invalidDrafts.length > 0} onClick={save}>{pending ? labels.saving : labels.save}</Button>}</div>
    </ContainerFooter>
  </Container>;
}

import type { ComponentPropsWithoutRef } from "react";
export type CostEstimateBilling = "monthly" | "annual";
export type CostEstimateCategory = "ingest" | "storage" | "queries" | "seats";
export type CostEstimateField = "ingestGBPerDay" | "retentionDays" | "scannedTBPerMonth" | "seats";
export interface CostEstimateUsage {
    ingestGBPerDay: number;
    retentionDays: number;
    scannedTBPerMonth: number;
    seats: number;
}
export interface CostEstimateInputs extends CostEstimateUsage {
    regionId: string;
    billing: CostEstimateBilling;
}
export interface CostEstimateRateCard {
    id: string;
    version: string;
    regionId: string;
    currency: string;
    minorUnitDigits: number;
    billingDays: number;
    compressionRatio: number;
    includedSeats: number;
    annualDiscountBps: number;
    minimumMonthlyMinor: number;
    /** Integer millionths of a major currency unit, as decimal strings. */
    ratesMicros: Record<CostEstimateCategory, string>;
}
export type CostEstimateLimits = Record<CostEstimateField, {
    min: number;
    max: number;
    step: number;
}>;
export interface CostEstimatePreset {
    id: string;
    label: string;
    usage: CostEstimateUsage;
}
export interface CostEstimateRegion {
    id: string;
    label: string;
    location: string;
}
export interface CostEstimateResult {
    inputs: CostEstimateInputs;
    rateCardId: string;
    rateCardVersion: string;
    currency: string;
    minorUnitDigits: number;
    amountsMinor: Record<CostEstimateCategory, number>;
    percentages: Record<CostEstimateCategory, number>;
    usageSubtotalMinor: number;
    minimumAdjustmentMinor: number;
    monthlyEquivalentMinor: number;
    monthlyBaselineMinor: number;
    annualTotalMinor: number | null;
    annualSavingsMinor: number | null;
    ingestGBMonth: number;
    storedGB: number;
    billableSeats: number;
    effectiveCostPerGB: number | null;
    /** Covers inputs and all pricing fields, not merely the version label. */
    fingerprint: string;
}
export type CostEstimateSaveState = {
    status: "idle" | "pending";
} | {
    status: "succeeded";
    fingerprint: string;
} | {
    status: "error";
    message: string;
};
export interface CostEstimateLabels {
    title: string;
    description: string;
    estimated: string;
    perMonth: string;
    monthly: string;
    annual: string;
    billing: string;
    annualAmount: string;
    savings: string;
    discount: string;
    breakdown: string;
    zeroUsage: string;
    usage: string;
    custom: string;
    preset: string;
    presets: string;
    ingest: string;
    storage: string;
    queries: string;
    seats: string;
    ingestUnit: string;
    retentionUnit: string;
    queriesUnit: string;
    seatsUnit: string;
    monthlyIngest: string;
    stored: string;
    compressed: string;
    includedSeats: string;
    billableSeats: string;
    minimumAdjustment: string;
    subtotal: string;
    effective: string;
    perGB: string;
    excludingTax: string;
    rateVersion: string;
    save: string;
    saving: string;
    saved: string;
    reset: string;
    loading: string;
    error: string;
    noRates: string;
    stale: string;
    invalid: string;
    invalidInput: string;
    retry: string;
}
export interface CostEstimateProps extends Omit<ComponentPropsWithoutRef<"div">, "children" | "onChange" | "title"> {
    value: CostEstimateInputs;
    onValueChange: (next: CostEstimateInputs, reason: "field" | "preset" | "reset" | "region" | "billing") => void;
    rateCard: CostEstimateRateCard | null;
    regions: readonly CostEstimateRegion[];
    presets?: readonly CostEstimatePreset[];
    limits?: CostEstimateLimits;
    defaultInputs?: CostEstimateInputs;
    state?: "ready" | "loading" | "stale" | "error";
    statusMessage?: string;
    saveState?: CostEstimateSaveState;
    actions?: {
        onSave?: (snapshot: CostEstimateResult) => void;
        onRetry?: () => void;
    };
    labels?: Partial<CostEstimateLabels>;
    title?: string;
    locale?: string;
}

import type { ChartColorIndex } from "@ui/chart-primitives";
import type { CostEstimateCategory, CostEstimateInputs, CostEstimateLabels, CostEstimateLimits, CostEstimateRateCard, CostEstimateResult, CostEstimateUsage } from "./cost-estimate-types";
export const costEstimateCategories: CostEstimateCategory[] = ["ingest", "storage", "queries", "seats"];
export const costEstimateColorIndices = { ingest: 1, storage: 2, queries: 3, seats: 4 } as const satisfies Record<CostEstimateCategory, ChartColorIndex>;
export const costEstimateDefaultLimits: CostEstimateLimits = {
    ingestGBPerDay: { min: 0, max: 1000, step: 0.5 }, retentionDays: { min: 1, max: 365, step: 1 },
    scannedTBPerMonth: { min: 0, max: 500, step: 0.5 }, seats: { min: 0, max: 100, step: 1 },
};
export const costEstimateLabels: CostEstimateLabels = {
    title: "费用估算", description: "调整用量，比较月付与年付的预计费用。",
    estimated: "预计费用", perMonth: "/ 月", monthly: "月付", annual: "年付", billing: "计费方式", annualAmount: "年付总额", savings: "预计节省", discount: "用量单价优惠",
    breakdown: "用量费用构成", zeroUsage: "当前用量费用为零", usage: "用量", custom: "自定义用量", preset: "当前预设", presets: "用量预设",
    ingest: "Ingest", storage: "Storage", queries: "Queries", seats: "Seats", ingestUnit: "GB / 天", retentionUnit: "天", queriesUnit: "TB / 月", seatsUnit: "席位",
    monthlyIngest: "月摄入", stored: "预计存储", compressed: "压缩比", includedSeats: "免费席位", billableSeats: "计费席位",
    minimumAdjustment: "最低消费补差", subtotal: "用量费用", effective: "每 GB 综合费用", perGB: "/ GB", excludingTax: "未含税", rateVersion: "费率版本",
    save: "保存估算", saving: "正在保存", saved: "已保存当前估算", reset: "重置", loading: "正在加载费率", error: "费率加载失败", noRates: "暂无可用费率",
    stale: "费率已过期，请刷新后保存。", invalid: "用量、范围或费率无效，无法估算。", invalidInput: "请输入范围内的有效数字。", retry: "重试",
};
// Six fractional digits are supported for quantities; pricing is calculated as integer ratios.
function quantity(value: number): bigint | null {
    if (!Number.isFinite(value) || value < 0 || value > 1000000)
        return null;
    const scaled = Math.round(value * 1000000);
    if (scaled === 0 && value !== 0)
        return null;
    if (Math.abs(value - scaled / 1000000) > Number.EPSILON * Math.max(1, value) * 4)
        return null;
    return BigInt(scaled);
}
export function costEstimateLimitsValid(limits: CostEstimateLimits): boolean {
    return (Object.keys(costEstimateDefaultLimits) as (keyof CostEstimateUsage)[]).every((field) => {
        const limit = limits[field];
        return limit && quantity(limit.min) !== null && quantity(limit.max) !== null && quantity(limit.step) !== null && limit.step > 0 && limit.min < limit.max
            && ((quantity(limit.max)! - quantity(limit.min)!) % quantity(limit.step)! === BigInt(0))
            && ((field !== "seats" && field !== "retentionDays") || [limit.min, limit.max, limit.step].every(Number.isInteger));
    }) && limits.retentionDays.min >= 1;
}
export function costEstimateUsageValid(value: CostEstimateUsage, limits: CostEstimateLimits): boolean {
    if (!costEstimateLimitsValid(limits))
        return false;
    return (Object.keys(costEstimateDefaultLimits) as (keyof CostEstimateUsage)[]).every((field) => {
        const q = quantity(value[field]);
        const { min, max, step } = limits[field];
        return q !== null && value[field] >= min && value[field] <= max && (q - quantity(min)!) % quantity(step)! === BigInt(0);
    });
}
export function costEstimateUsageMatches(a: CostEstimateUsage, b: CostEstimateUsage): boolean {
    return a.ingestGBPerDay === b.ingestGBPerDay && a.retentionDays === b.retentionDays && a.scannedTBPerMonth === b.scannedTBPerMonth && a.seats === b.seats;
}
function roundRatio(numerator: bigint, denominator: bigint): bigint {
    return (numerator * BigInt(2) + denominator) / (denominator * BigInt(2));
}
/** Returns null on invalid input, mismatched pricing, or unsafe output; never substitutes zero. */
export function calculateCostEstimate(value: CostEstimateInputs, rate: CostEstimateRateCard, limits: CostEstimateLimits = costEstimateDefaultLimits): CostEstimateResult | null {
    if (!costEstimateUsageValid(value, limits) || !value.regionId || rate.regionId !== value.regionId || !["monthly", "annual"].includes(value.billing)
        || !rate.id || !rate.version || !/^[A-Z]{3}$/.test(rate.currency) || !Number.isInteger(rate.minorUnitDigits) || rate.minorUnitDigits < 0 || rate.minorUnitDigits > 6
        || !Number.isSafeInteger(rate.billingDays) || rate.billingDays <= 0 || rate.billingDays > 366 || quantity(rate.compressionRatio) === null || rate.compressionRatio <= 0
        || !Number.isSafeInteger(rate.includedSeats) || rate.includedSeats < 0 || !Number.isInteger(rate.annualDiscountBps) || rate.annualDiscountBps < 0 || rate.annualDiscountBps > 10000
        || !Number.isSafeInteger(rate.minimumMonthlyMinor) || rate.minimumMonthlyMinor < 0 || !rate.ratesMicros
        || costEstimateCategories.some((key) => typeof rate.ratesMicros[key] !== "string" || !/^\d{1,18}$/.test(rate.ratesMicros[key])))
        return null;
    const scale = BigInt(1000000);
    const compression = quantity(rate.compressionRatio)!;
    const ingest = quantity(value.ingestGBPerDay)!;
    const scanned = quantity(value.scannedTBPerMonth)!;
    const billableSeats = Math.max(value.seats - rate.includedSeats, 0);
    const ratios: Record<CostEstimateCategory, [
        bigint,
        bigint
    ]> = {
        ingest: [ingest * BigInt(rate.billingDays), scale],
        storage: [ingest * BigInt(value.retentionDays), compression],
        queries: [scanned, scale], seats: [BigInt(billableSeats), BigInt(1)],
    };
    function amounts(discountBps: number) {
        return costEstimateCategories.map((key) => {
            const [n, d] = ratios[key];
            return roundRatio(n * BigInt(rate.ratesMicros[key]) * BigInt(10 ** rate.minorUnitDigits) * BigInt(10000 - discountBps), d * scale * BigInt(10000));
        });
    }
    const lines = amounts(value.billing === "annual" ? rate.annualDiscountBps : 0);
    const subtotal = lines.reduce((sum, amount) => sum + amount, BigInt(0));
    const minimum = BigInt(rate.minimumMonthlyMinor);
    const monthly = subtotal > minimum ? subtotal : minimum;
    const baseSubtotal = amounts(0).reduce((sum, amount) => sum + amount, BigInt(0));
    const baseline = baseSubtotal > minimum ? baseSubtotal : minimum;
    // Reserve enough integer precision for the annual projection and percentages.
    if (baseline * BigInt(12) > BigInt(Number.MAX_SAFE_INTEGER))
        return null;
    const fractions = lines.map((amount, index) => ({ index, whole: subtotal > BigInt(0) ? Number(amount * BigInt(100) / subtotal) : 0, remainder: subtotal > BigInt(0) ? amount * BigInt(100) % subtotal : BigInt(0) }));
    let remaining = subtotal > BigInt(0) ? 100 - fractions.reduce((sum, item) => sum + item.whole, 0) : 0;
    [...fractions].sort((a, b) => a.remainder === b.remainder ? a.index - b.index : a.remainder > b.remainder ? -1 : 1).forEach((item) => { if (remaining > 0) {
        item.whole++;
        remaining--;
    } });
    const ingestGBMonth = value.ingestGBPerDay * rate.billingDays;
    return {
        inputs: { ...value }, rateCardId: rate.id, rateCardVersion: rate.version, currency: rate.currency, minorUnitDigits: rate.minorUnitDigits,
        amountsMinor: Object.fromEntries(costEstimateCategories.map((key, i) => [key, Number(lines[i])])) as CostEstimateResult["amountsMinor"],
        percentages: Object.fromEntries(costEstimateCategories.map((key, i) => [key, fractions[i].whole])) as CostEstimateResult["percentages"],
        usageSubtotalMinor: Number(subtotal), minimumAdjustmentMinor: Number(monthly - subtotal), monthlyEquivalentMinor: Number(monthly), monthlyBaselineMinor: Number(baseline),
        annualTotalMinor: value.billing === "annual" ? Number(monthly * BigInt(12)) : null,
        annualSavingsMinor: value.billing === "annual" ? Number((baseline - monthly) * BigInt(12)) : null,
        ingestGBMonth, storedGB: value.ingestGBPerDay * value.retentionDays / rate.compressionRatio, billableSeats,
        effectiveCostPerGB: ingestGBMonth > 0 ? Number(monthly) / 10 ** rate.minorUnitDigits / ingestGBMonth : null,
        fingerprint: JSON.stringify([value.regionId, value.billing, value.ingestGBPerDay, value.retentionDays, value.scannedTBPerMonth, value.seats, rate.id, rate.version, rate.currency, rate.minorUnitDigits, rate.billingDays, rate.compressionRatio, rate.includedSeats, rate.annualDiscountBps, rate.minimumMonthlyMinor, ...costEstimateCategories.map((key) => rate.ratesMicros[key])]),
    };
}
export function costEstimateMoney(amountMinor: number, result: Pick<CostEstimateResult, "currency" | "minorUnitDigits">, locale: string): string {
    return new Intl.NumberFormat(locale, { style: "currency", currency: result.currency, minimumFractionDigits: result.minorUnitDigits, maximumFractionDigits: result.minorUnitDigits }).format(amountMinor / 10 ** result.minorUnitDigits);
}

"use client";
import { Badge } from "@ui/badge";
import { chartColor, SegmentedBar } from "@ui/chart-primitives";
import { Tabs, TabsList, TabItem, TabPanel } from "@ui/tabs";
import { costEstimateCategories, costEstimateColorIndices, costEstimateMoney } from "./cost-estimate-data";
import type { CostEstimateLabels, CostEstimateRateCard, CostEstimateResult } from "./cost-estimate-types";
export function CostEstimateSummary({ result, rateCard, labels, locale, onBillingChange }: {
    result: CostEstimateResult;
    rateCard: CostEstimateRateCard;
    labels: CostEstimateLabels;
    locale: string;
    onBillingChange: (billing: "monthly" | "annual") => void;
}) {
    const money = (minor: number) => costEstimateMoney(minor, result, locale);
    const annual = result.inputs.billing === "annual";
    const segments = costEstimateCategories.map((key) => ({ id: key, label: labels[key], value: result.amountsMinor[key], color: chartColor(costEstimateColorIndices[key]) }));
    return <Tabs value={result.inputs.billing} variant="pill" color="default" onValueChange={(value) => { if (value === "monthly" || value === "annual")
        onBillingChange(value); }} className="space-y-4">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div className="min-w-0"><p className="text-label text-fg-subtle">{labels.estimated}</p>
        <p className="mt-1 flex flex-wrap items-baseline gap-2">{annual && result.monthlyBaselineMinor !== result.monthlyEquivalentMinor && <del className="text-body tabular-nums text-fg-subtle">{money(result.monthlyBaselineMinor)}</del>}<span data-slot="cost-estimate-total" className="break-all text-heading font-semibold tabular-nums text-fg-default">{money(result.monthlyEquivalentMinor)}</span><span className="text-label text-fg-subtle">{labels.perMonth}</span></p>
      </div>
      <TabsList aria-label={labels.billing} className="ml-auto shrink-0">
        <TabItem value="monthly" label={labels.monthly}/><TabItem value="annual" label={labels.annual}/>
      </TabsList>
    </div>
    {(["monthly", "annual"] as const).map((billing) => <TabPanel key={billing} value={billing} className="space-y-4">
      {billing === result.inputs.billing && <>
    <div className="space-y-1 text-label text-fg-muted">
      {rateCard.annualDiscountBps > 0 && <Badge status="success" size="sm">{labels.annual} · {labels.discount} {new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 2 }).format(rateCard.annualDiscountBps / 10000)}</Badge>}
      {annual && <p>{labels.annualAmount} {money(result.annualTotalMinor!)} · {labels.savings} {money(result.annualSavingsMinor!)}</p>}
      {result.minimumAdjustmentMinor > 0 && <p>{labels.subtotal} {money(result.usageSubtotalMinor)} + {labels.minimumAdjustment} {money(result.minimumAdjustmentMinor)} = {money(result.monthlyEquivalentMinor)}</p>}
      <p>{labels.effective} {result.effectiveCostPerGB === null ? "—" : new Intl.NumberFormat(locale, { style: "currency", currency: result.currency, minimumFractionDigits: 2, maximumFractionDigits: 4 }).format(result.effectiveCostPerGB)} {labels.perGB}</p>
    </div>
    <div className="space-y-3">
      <h3 className="text-body font-medium text-fg-default">{labels.breakdown}</h3>
      {result.usageSubtotalMinor > 0 ? <div className="flex h-5 items-center"><SegmentedBar mode="distribution" total={result.usageSubtotalMinor} segments={segments} valueText={`${labels.breakdown}: ${costEstimateCategories.map((key) => `${labels[key]} ${money(result.amountsMinor[key])} (${result.percentages[key]}%)`).join("; ")}`}/></div> : <p className="text-label text-fg-muted">{labels.zeroUsage}</p>}
      <dl className="grid grid-cols-2 gap-3">{costEstimateCategories.map((key) => <div className="flex min-w-0 items-center justify-between gap-0.5 @lg:gap-2" key={key}>
        <dt className="shrink-0"><Badge variant="dot" color={{ base: chartColor(costEstimateColorIndices[key]), onStrong: "var(--fg-default)" }} size="sm">{labels[key]}</Badge></dt>
        <dd className="flex min-w-0 flex-wrap items-baseline justify-end gap-x-1.5 gap-y-0.5 text-right text-label tabular-nums @lg:text-body"><span className="break-all font-medium text-fg-default">{money(result.amountsMinor[key])}</span><span className="text-label text-fg-subtle">{result.percentages[key]}%</span></dd>
      </div>)}</dl>
    </div>
      </>}
    </TabPanel>)}
  </Tabs>;
}

"use client";
import { useEffect, useId, useRef, useState } from "react";
import { chartColor } from "@ui/chart-primitives";
import { Field, FieldDescription, FieldLabel } from "@ui/field";
